-- Runtime OFF switch is Studio-only and never creates a second authority.
-- Default ON in unpublished Studio testing. Set BoolValue false for instant OFF.
local function classicRelayEnabled(): boolean
    if not RunService:IsStudio() then return false end
    local flag = game:GetService("ServerStorage"):FindFirstChild("P0D_RC_ENABLE_EGG_RELAY_CLASSIC")
    return flag == nil or (flag:IsA("BoolValue") and flag.Value == true)
end
